select
*
from b_xiecheng_sms_colliding_data
where  status =1  and local_id = #{localId}
   and retry_count > 0 and retry_count < 3

    and id > #{minId}

order by id asc limit 15000;

select
*
from b_xiecheng_sms_colliding_data
where  status =1  and local_id = #{localId}
and retry_count =3

    and id > #{minId}

order by id asc limit 15000;

select
*
from b_xiecheng_sms_colliding_data
where  status =1  and local_id = #{localId} and retry_count =0


           and next_push_time <= #{endTime}  


           and next_push_time <=> null  



    and id > #{minId}

order by id asc limit 15000;

